func TestConsumeSSEHeartbeatsKeepStreamAliveUntilStatus(t *testing.T) {
	server := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if got := r.Header.Get("Authorization"); got != "Bearer test-token" {
			t.Errorf("authorization=%q", got)
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		w.Header().Set("Content-Type", "text/event-stream")
		flusher := w.(http.Flusher)
		for range 4 {
			fmt.Fprint(w, ": heartbeat\n\n")
			flusher.Flush()
			time.Sleep(10 * time.Millisecond)
		}
		fmt.Fprint(w, "event: status\ndata: {\"health\":{\"code\":0},\"activity\":{\"active\":true}}\n\n")
		flusher.Flush()
	}))
	defer server.Close()

	var got statusInput
	err := consumeSSE(context.Background(), server.Client(), server.URL, "test-token", 25*time.Millisecond, func(input statusInput) {
		got = input
	})
	if !errors.Is(err, errStreamEnded) {
		t.Fatalf("consumeSSE error=%v, want stream ended", err)
	}
	if !got.connected || got.healthCode != 0 || !got.active {
		t.Fatalf("decoded status=%+v", got)
	}
}

func TestConsumeSSETimesOutWhenNoBytesArrive(t *testing.T) {
	server := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/event-stream")
		w.WriteHeader(http.StatusOK)
		w.(http.Flusher).Flush()
		<-r.Context().Done()
	}))
	defer server.Close()

	started := time.Now()
	err := consumeSSE(context.Background(), server.Client(), server.URL, "test-token", 20*time.Millisecond, func(statusInput) {})
	if !errors.Is(err, errStreamTimeout) {
		t.Fatalf("consumeSSE error=%v, want stream timeout", err)
	}
	if elapsed := time.Since(started); elapsed > 500*time.Millisecond {
		t.Fatalf("timeout took %s", elapsed)
	}
}

func TestConsumeSSERecoversCoalescedShortActivityFromPollSequence(t *testing.T) {
	server := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/event-stream")
		fmt.Fprint(w, "event: status\ndata: {\"health\":{\"code\":0},\"activity\":{\"active\":false,\"poll_sequence\":10}}\n\n")
		fmt.Fprint(w, "event: status\ndata: {\"health\":{\"code\":0},\"activity\":{\"active\":false,\"poll_sequence\":11}}\n\n")
	}))
	defer server.Close()

	var got []statusInput
	err := consumeSSE(context.Background(), server.Client(), server.URL, "test-token", time.Second, func(input statusInput) {
		got = append(got, input)
	})
	if !errors.Is(err, errStreamEnded) {
		t.Fatalf("consumeSSE error=%v, want stream ended", err)
	}
	if len(got) != 3 || got[0].active || !got[1].active || got[2].active {
		t.Fatalf("coalesced activity callbacks=%+v, want idle, synthetic active, idle", got)
	}
}

func TestConsumeSSERejectsOversizedOrInvalidStatus(t *testing.T) {
	server := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/event-stream")
		fmt.Fprint(w, "event: status\ndata: {\"health\":{\"code\":9},\"activity\":{\"active\":false}}\n\n")
	}))
	defer server.Close()

	err := consumeSSE(context.Background(), server.Client(), server.URL, "test-token", time.Second, func(statusInput) {})
	if err == nil || errors.Is(err, errStreamEnded) {
		t.Fatalf("invalid health status was accepted: %v", err)
	}
}
